import java.util.*;

public class Ex05ConfigPrecedence {
    static String get(List<Map<String, String>> sources, String key) {
        for (Map<String, String> s : sources) if (s.containsKey(key)) return s.get(key);
        return "<none>";
    }

    public static void main(String[] args) {
        List<Map<String, String>> sources = new ArrayList<>();
        sources.add(new LinkedHashMap<>(Map.of("server.port", "9090")));                                 // 1 命令行
        sources.add(new LinkedHashMap<>(Map.of("app.name", "from-os-env")));                             // 2 环境变量
        sources.add(new LinkedHashMap<>(Map.of("server.port", "8081", "app.name", "outer-profile")));    // 3 jar外 profile
        sources.add(new LinkedHashMap<>(Map.of("server.port", "8080", "app.name", "inner-profile")));    // 4 jar内 profile
        sources.add(new LinkedHashMap<>(Map.of("server.port", "80", "app.name", "inner-default")));      // 5 jar内默认

        String[] names = {
            "command line args",
            "os environment",
            "jar-external application-prod.properties",
            "jar-internal application-prod.properties",
            "jar-internal application.properties"
        };

        System.out.println("get(server.port) = " + get(sources, "server.port"));
        System.out.println("get(app.name)    = " + get(sources, "app.name"));
        System.out.println("--- source order (high -> low) ---");
        for (int i = 0; i < names.length; i++) System.out.println("  " + (i + 1) + ". " + names[i]);
    }
}
